import { test } from 'node:test';
import assert from 'node:assert/strict';
import { receiptTotal } from '../src/total.js';

test('lines are summed', () => {
  assert.equal(receiptTotal([{ price: 120, qty: 2 }, { price: 300, qty: 1 }]), 540);
});

test('no discount keeps the subtotal', () => {
  assert.equal(receiptTotal([{ price: 999, qty: 1 }], 0), 999);
});

// #42
test('300 yen at 30 % is 210 yen', () => {
  assert.equal(receiptTotal([{ price: 300, qty: 1 }], 30), 210);
});

// PR #43 review: a discount that is not a whole percent from 0 to 100 is refused, not computed
for (const percent of [-5, -1, 101, 120, 12.5, NaN]) {
  test(`a discount of ${percent} % is a RangeError`, () => {
    assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], percent), RangeError);
  });
}

test('a discount of 100 % is allowed and leaves 0 yen', () => {
  assert.equal(receiptTotal([{ price: 300, qty: 1 }], 100), 0);
});
